package com.crm.customer.repository;import com.crm.customer.entity.ClientCase;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import org.springframework.data.domain.*;import java.util.Optional;
public interface ClientCaseRepository extends JpaRepository<ClientCase,Long> {Optional<ClientCase> findByRequestId(String id);@Lock(jakarta.persistence.LockModeType.PESSIMISTIC_WRITE) @Query("select c from ClientCase c where c.id=:id") Optional<ClientCase> lock(@Param("id") long id);@Query("select c from ClientCase c where (:customer is null or c.customerId=:customer) and (:status is null or c.status=:status)") Page<ClientCase> search(@Param("customer") Long customer,@Param("status") String status,Pageable page);}
